import{at as e,it as t,n,vt as r}from"./chunks/framework.B6nQ8gjX.js";var i=JSON.parse(`{"title":"Locked servers","description":"","frontmatter":{},"headers":[],"relativePath":"guide/unlock.md","filePath":"guide/unlock.md","lastUpdated":1793799577000}`),a={name:`guide/unlock.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="locked-servers" tabindex="-1">Locked servers <a class="header-anchor" href="#locked-servers" aria-label="Permalink to “Locked servers”">​</a></h1><p>Some servers are too powerful to be at every model&#39;s disposal at every moment. A shell, a mailbox that can send, the DNS of your domains. Any client that holds a token for the hub can call them, and so can a token that leaked or a model that a web page or an e-mail talked into it.</p><p><code>unlock</code> keeps such a server locked until a person unlocks it. A model that calls one of its tools gets a link instead of a result. You open the link, prove that you are there with the operator password (and the <a href="/guide/two-factor">second factor</a>, if it is on), and pick how long: only this call, or 15 minutes up to four hours. Only the connection that asked is unlocked, and only for that long.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to “Configuration”">​</a></h2><div class="language-jsonc" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">jsonc</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">{</span></span>
<span class="line"><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">  &quot;mcpServers&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: {</span></span>
<span class="line"><span style="--shiki-light:#6E7781;--shiki-dark:#8B949E;">    // every tool, resource and prompt locked, unlocks up to 4 hours</span></span>
<span class="line"><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">    &quot;ssh&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: { </span><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">&quot;type&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;docker&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">, </span><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">&quot;image&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;…&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">, </span><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">&quot;unlock&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;">true</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;"> },</span></span>
<span class="line"><span style="--shiki-light:#6E7781;--shiki-dark:#8B949E;">    // only these tools locked, unlocks up to 2 hours</span></span>
<span class="line"><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">    &quot;smtp&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: { </span><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">&quot;command&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;smtp-mcp&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">, </span><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">&quot;unlock&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: { </span><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">&quot;tools&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: [</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;send_mail&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">, </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;reply_mail&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">, </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;forward_mail&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">], </span><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">&quot;maxMinutes&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;">120</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;"> } }</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">  }</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">}</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Field</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td><code>tools</code></td><td><code>[&quot;*&quot;]</code></td><td>The tools that stay locked, in the <a href="/guide/configuration#filtering-tools"><code>allowTools</code> syntax</a>: exact names or a trailing <code>*</code>. <code>&quot;*&quot;</code> locks the whole server: tools, resources, prompts, completions and subscriptions. A list locks just those tools and leaves everything else of the server free.</td></tr><tr><td><code>maxMinutes</code></td><td><code>240</code></td><td>The longest unlock the page offers, from <code>0</code> (single calls only) to <code>240</code>.</td></tr></tbody></table><p><code>&quot;unlock&quot;: true</code> is short for <code>{ &quot;tools&quot;: [&quot;*&quot;] }</code>. The fields are checked strictly, and an unknown field stops the config from loading. A misspelt key next to <code>unlock</code> (<code>&quot;unlok&quot;</code>) is <a href="/guide/configuration#validation-errors">warned about</a> rather than ignored in silence. Entries in <code>tools</code> that match none of the server&#39;s tools are warned about when its tool list arrives: such a typo would leave a tool unlocked.</p><p>Changing <code>tools</code> or <code>maxMinutes</code> takes effect at once without restarting the server. Adding or removing <code>unlock</code> restarts it.</p><div class="warning custom-block"><p class="custom-block-title">A hub older than 0.12 ignores <code>unlock</code></p><p>Upgrade the hub first, then add the key. An older hub, or a rollback to one, runs a server with <code>unlock</code> as if it were not locked. The boot log names every locked server (<code>locked until unlocked: …</code>), so check for that line.</p></div><h2 id="what-a-model-sees" tabindex="-1">What a model sees <a class="header-anchor" href="#what-a-model-sees" aria-label="Permalink to “What a model sees”">​</a></h2><p>The locked server&#39;s tools stay listed, so a model knows they exist. <code>list_servers</code> marks them, with <code>locked</code>, the <code>lockedTools</code> when it is not all of them, and <code>unlockedUntil</code> when the caller holds an unlock.</p><p>A call to a locked tool does not reach the server. The answer depends on the client:</p><ul><li><strong>Clients that can open pages themselves</strong> (URL-mode elicitation: Claude Code, VS Code, the MCP Inspector) are asked through the client. It shows the hub&#39;s address, the server, the tool and the matching code, opens the page with your consent, and retries the call once you are done.</li><li><strong>Every other client</strong> (claude.ai, ChatGPT, …) gets an error result with the link and the matching code, and the instruction to ask you and then call again.</li></ul><p>On a hub that locks something, two more meta-tools appear on <code>/hub</code>:</p><ul><li><code>request_unlock</code> hands out the link before the first call.</li><li><code>lock_server</code> ends the caller&#39;s own unlocks once it is done. It can never unlock anything.</li></ul><h2 id="the-page" tabindex="-1">The page <a class="header-anchor" href="#the-page" aria-label="Permalink to “The page”">​</a></h2><p>The link opens a page on the hub. It shows what the hub itself recorded:</p><ul><li>the server, and what is locked on it;</li><li>the client and the time;</li><li>the matching code, the same one the model was given;</li><li>for a locked call, the tool and its exact arguments, marked as written by the model.</li></ul><p>Compare the code with the one in your chat. If it differs, or you did not start this, press <strong>Deny</strong>: the model is told, and the same ask is held off for two minutes.</p><p>To unlock, choose a duration, enter the password and, with two-factor login on, the code from your authenticator, and press <strong>Unlock</strong>. <em>Only this call</em> unlocks exactly that call with exactly those arguments, once. The page offers it when the arguments are short enough to show in full. The durations stop at the server&#39;s <code>maxMinutes</code>, and an unlock ends at a fixed time: using the server does not extend it. To keep going, unlock again.</p><p>The link works for ten minutes and once. It unlocks nothing by itself. Every unlock needs the factors, and wrong ones count exactly as on the login page: toward the per-address limit and the pause after wrong codes, with the same log lines.</p><p><strong><code>/unlock</code> is worth a bookmark.</strong> Sign in there and it shows:</p><ul><li>the open requests with their codes, to unlock or deny;</li><li>what is unlocked right now, with a <em>Lock now</em> button for each;</li><li>a form to unlock a server ahead of a call for an approved client.</li></ul><p>With the bookmark you never need a link a model gave you.</p><h2 id="who-is-unlocked" tabindex="-1">Who is unlocked <a class="header-anchor" href="#who-is-unlocked" aria-label="Permalink to “Who is unlocked”">​</a></h2><p><strong>The authorization that asked, and only that.</strong> One authorization is one connector you added in one client: the <code>/ssh/mcp</code> connector in claude.ai, or one Claude Code installation. Another client stays locked, and so does another installation of the same client.</p><p>Within one authorization, an unlock covers everything that authorization does. All your claude.ai conversations use the same connector, so a 30-minute unlock started from one conversation also covers the others.</p><p>Admin API tokens are unlocked per token. An unlock made from the overview page or the admin CLI covers every authorization of the client you pick.</p><h2 id="when-an-unlock-ends" tabindex="-1">When an unlock ends <a class="header-anchor" href="#when-an-unlock-ends" aria-label="Permalink to “When an unlock ends”">​</a></h2><p>It expires, you press <em>Lock now</em>, the model calls <code>lock_server</code>, or <code>mcp-hub-admin unlock revoke</code> ends it. From then on the server&#39;s locked tools are refused again, and calls already running are allowed to finish.</p><p>When the last unlock of a server that locks everything has ended, the hub waits for those calls (up to five minutes) and then ends what the server holds. A call admitted just before the end may still be waiting for the server to start; the hub then waits for the start to settle and for that call as well. An <a href="/guide/on-demand">on-demand</a> server goes to sleep, an always-on one restarts. A shell session or a connection that was opened while the server was unlocked does not outlive the unlock. A server that locks only some tools keeps running, because its other tools are free.</p><h2 id="from-the-host" tabindex="-1">From the host <a class="header-anchor" href="#from-the-host" aria-label="Permalink to “From the host”">​</a></h2><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#953800;--shiki-dark:#FFA657;">mcp-hub-admin</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> unlock</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> list</span></span>
<span class="line"><span style="--shiki-light:#953800;--shiki-dark:#FFA657;">mcp-hub-admin</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> unlock</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> grant</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;"> &lt;</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">serve</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">r</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">&gt;</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;"> &lt;</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">minute</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">s</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">&gt;</span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;"> --client</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;"> &lt;</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">client-i</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">d</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#953800;--shiki-dark:#FFA657;">mcp-hub-admin</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> unlock</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> revoke</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;"> &lt;</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">serve</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">r</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">&gt;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;"> [--client </span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">&lt;</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">client-i</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">d</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">&gt;</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">]</span></span></code></pre></div><p>This is the way in without a phone, or for a hub without a usable sign-in. See the <a href="/reference/admin-cli#unlock">admin CLI</a>.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to “Limits”">​</a></h2><ul><li><strong>An unlock is a window, and whatever runs in it runs.</strong> A model that is being manipulated while the server is unlocked can use it like any other call. Prefer short windows, or <em>only this call</em>, and lock again when you are done.</li><li><strong>A server that administers the hub&#39;s own host can switch the lock off.</strong> A shell that runs <code>docker</code> on the machine the hub runs on can reach the hub&#39;s container, its environment and its config while it is unlocked. Keep such a server&#39;s own permissions narrow. The lock is not a sandbox.</li><li><strong>A link from a model can be a fake.</strong> The page lives on your hub&#39;s address and nowhere else, so check the address before you type the password. The <code>/unlock</code> bookmark avoids the question altogether.</li><li><strong>Over stdio nothing can be unlocked.</strong> There is no page to unlock on, so locked tools stay shut in <code>--stdio</code> mode.</li></ul>`,36)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};